export type LienNoticePolicy = 'ask' | 'send' | 'hold'

export const LIEN_NOTICE_POLICIES: ReadonlyArray<{ key: LienNoticePolicy; label: string; hint: string }> = [
  { key: 'ask', label: 'Ask me each time', hint: 'Every notice for this GC comes to you before it goes out.' },
  { key: 'send', label: 'Send notices without asking', hint: 'From the second notice on — the first one to a GC always comes to you. The office sends on schedule; you see each send in your FYI list.' },
  { key: 'hold', label: "Hold — I'll call first", hint: 'Every month parks until you say so; the desk re-asks three days before each deadline.' },
]

export function parseLienNoticePolicy(v: unknown): LienNoticePolicy {
  return v === 'send' || v === 'hold' ? v : 'ask'
}

export type LienDeskPile = 'needs_owner' | 'to_draft' | 'awaiting' | 'ready' | 'printed' | 'held' | 'sent' | 'missed'

/**
 * What an empty, narrowed pile says (v2.4854): the pile by name, in the words of
 * what is no longer there, and how many notices the other piles hold — so a
 * leader who approved the last one is not left with "Nothing in this pile."
 */
export function lienEmptyPileWords(pile: LienDeskPile, onOtherPiles: number): { head: string; rest: string } {
  const head: Record<LienDeskPile, string> = {
    needs_owner: 'Every notice has its owner of record.',
    to_draft: 'Nothing is left to send for approval.',
    awaiting: 'Nothing is waiting for approval.',
    ready: 'Nothing approved is waiting to print.',
    printed: 'Nothing printed is waiting on its mail numbers.',
    held: 'Nothing is held.',
    sent: 'Nothing went out in the last 30 days.',
    missed: 'No window was missed.',
  }
  const rest = onOtherPiles > 0 ? `${onOtherPiles} ${onOtherPiles === 1 ? 'notice is' : 'notices are'} on the other piles.` : 'The other piles are empty too.'
  return { head: head[pile], rest }
}

